package com.dronefleet.security;import com.dronefleet.domain.Role;import com.dronefleet.repository.UserRepository;import java.util.Optional;
public final class AuthService{private final UserRepository users;public AuthService(UserRepository users){this.users=users;}public void ensureDefaults(){if(users.find("admin").isEmpty())users.save("admin",PasswordHasher.hash("admin123"),Role.ADMIN);if(users.find("operator").isEmpty())users.save("operator",PasswordHasher.hash("operator123"),Role.OPERATOR);}public Optional<Session> login(String u,String p){return users.find(u).filter(x->PasswordHasher.verify(p,x.hash())).map(x->new Session(x.username(),x.role()));}}
